import base64, io, os
from PIL import Image

# 아이콘 원본 (base64 내장 — LFS 의존성 없음)
_ICON_B64 = ""

try:
    img = Image.open(io.BytesIO(base64.b64decode(_ICON_B64))).convert("RGBA")
    for size, path in [(192, "frontend/public/icon-192.png"),
                       (512, "frontend/public/icon-512.png"),
                       (180, "frontend/public/apple-touch-icon.png")]:
        img.resize((size, size), Image.LANCZOS).save(path, "PNG")
        print(f"Icon {size}x{size} -> {path}")
except Exception as e:
    print(f"Icon generation error: {e}")
